package com.adsh.app.ui

import androidx.compose.animation.core.LinearEasing
import androidx.compose.animation.core.animateFloat
import androidx.compose.animation.core.infiniteRepeatable
import androidx.compose.animation.core.rememberInfiniteTransition
import androidx.compose.animation.core.tween
import androidx.compose.foundation.Canvas
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.drawscope.Stroke

/**
 * dsh 0.2.0-rc.1 的 `RunningWhaleTail` —— 会话运行中「深度求索中…」左边那条鲸鱼尾
 * （ADSH 里对应「吃白饭中...」那一行，第 99 轮用户点名要一个）。
 *
 * **逐字搬过来的**是 `REST_PATH` / `MOTION_PATHS`（22 个关键帧）/ `MOTION_TIMES`，
 * 以及它的行为：16×16 的描边路径（`strokeWidth 1`、`stroke: currentColor`）做**路径变形**，
 * `begin 0.3s`、`dur 3s`、`repeatCount indefinite`、`calcMode linear`。
 * 每一帧的形态 = 相邻关键帧按 `MOTION_TIMES` **逐坐标线性插值** —— 22 个关键帧的命令结构完全一致
 * （`M` + 15 段三次贝塞尔、92 个坐标，dsh 的注释也写明「Same cubic segments in every pose」），
 * 所以与 SVG `animate` 对 `d` 的线性插值等价。
 *
 * dsh 在 `prefers-reduced-motion` 下把动画那条 path 藏起来、换成静止的 `REST_PATH`；
 * 这里不另读系统设置：Compose 的 `MotionDurationScale`（系统「动画时长」设为 0 时）会把 tween
 * 时长压成 0，整条链停在最后一帧 = REST_PATH，正好就是那个静止形态（与运行扫光同一条口径）。
 *
 * 动画值**只在绘制阶段读**（`Canvas` 的 lambda 里）：读进组合体就等于每帧重组整行 ——
 * 第 95 轮扫光「两个时钟相加」的坑就是这么来的。
 *
 * @param tint 单色描边（默认）。与 [brush] 二选一，给了 brush 就用 brush。
 * @param brush 「吃白饭中」那一行的流光要从尾巴上扫过去（第 101 轮用户点名），
 *   于是尾巴也要能用渐变描边 —— 画笔坐标是**画布像素**（与相邻那段流光文字共用同一套
 *   坐标），所以路径坐标在这里直接乘进像素、不再用 `scale` 变换：变换过的话同一段渐变
 *   在尾巴上会被再缩放一次，与文字那边就对不齐了。
 */
@Composable
fun RunningWhaleTail(modifier: Modifier = Modifier, tint: Color, brush: Brush? = null) {
    val transition = rememberInfiniteTransition(label = "whaleTail")
    val phase = transition.animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(
            // 一个循环 = 0.3s 静止 + 3s 变形（对应 SVG 的 begin/dur；delay 放在周期里而不是
            // animationSpec 的 delayMillis 上，否则每一轮之间都会多插一次 0.3s 停顿）
            animation = tween(durationMillis = CYCLE_MS, easing = LinearEasing),
        ),
        label = "whaleTailPhase",
    )
    // 每帧复用的坐标缓冲（92 个数）：绘制阶段每帧都算一次形态，别每帧再分配一个数组
    val pose = remember { FloatArray(WHALE_FRAME_SIZE) }
    Canvas(modifier) {
        val raw = phase.value * CYCLE_MS
        val t = ((raw - START_DELAY_MS) / LOOP_MS).coerceIn(0f, 1f)
        // 关键帧坐标是 16×16 的 viewBox：按实际边长缩放（描边宽度也按同一比例 = 1/16 边长），
        // 缩放**乘进坐标本身**，让画笔工作在普通画布像素上（见 brush 的说明）
        val s = size.minDimension / VIEWPORT
        val scaled = whalePoseAt(t, pose)
        for (k in scaled.indices) scaled[k] *= s
        val path = Path().apply { appendPose(scaled) }
        if (brush != null) {
            drawPath(path, brush = brush, style = Stroke(width = s))
        } else {
            drawPath(path, color = tint, style = Stroke(width = s))
        }
    }
}

/**
 * dsh 的 `runningIcon`：`calc(14px + var(--dsh-content-font-delta))` —— 默认字号下就是 14px。
 *
 * **第 105 轮改成 16dp**（用户点名：「文字变细后，尾巴大一点更平衡」）：与 dsh 的唯一有意偏离，
 * 缩进常量 [TURN_STATUS_INDENT_DP] 跟着它一起变（尾巴 + 间隔），所以「吃」字仍然落在原来的位置。
 */
internal const val WHALE_TAIL_SIZE_DP = 16

/** dsh 的 `runningContent { gap: 6px }`：鲸鱼与文字之间 */
internal const val WHALE_TAIL_GAP_DP = 6

private const val VIEWPORT = 16f
/** dsh 的 `begin: 0.3s` */
private const val START_DELAY_MS = 300
/** dsh 的 `dur: 3s` */
private const val LOOP_MS = 3000
/** 一个循环的总长（静止 + 变形）；tween 要的是整型毫秒 */
private const val CYCLE_MS = START_DELAY_MS + LOOP_MS

