/** dsh 的 `MOTION_TIMES`（逐字）：每个关键帧在 3s 循环里的位置 */
private val WHALE_TIMES: FloatArray = floatArrayOf(0f, 0.028571f, 0.057143f, 0.095238f, 0.114286f, 0.133333f, 0.171429f, 0.2f, 0.219048f, 0.257143f, 0.285714f, 0.380952f, 0.409524f, 0.447619f, 0.47619f, 0.495238f, 0.52381f, 0.552381f, 0.571429f, 0.638095f, 0.8f, 1f)

private val NUMBER = Regex("""-?\d+(?:\.\d+)?""")

/** 把每个关键帧的坐标抽出来（命令结构一致，所以只需要坐标序列） */
private val WHALE_FRAMES: List<FloatArray> = WHALE_POSES.map { pose ->
    NUMBER.findAll(pose).map { it.value.toFloat() }.toList().toFloatArray()
}

private fun lerp(a: Float, b: Float, f: Float) = a + (b - a) * f

/** 一帧的坐标个数（= 22 个关键帧共同的形状：2 + 15×6 = 92） */
internal val WHALE_FRAME_SIZE: Int get() = WHALE_FRAMES.first().size

/** 关键帧个数（测试用；dsh 的 `MOTION_PATHS` 长度） */
internal val WHALE_FRAME_COUNT: Int get() = WHALE_FRAMES.size

/** 测试用：第 i 个关键帧的坐标（原始数据，未插值） */
internal fun whaleFrame(i: Int): FloatArray = WHALE_FRAMES[i]

/** 按 `WHALE_TIMES` 找到 t 落在哪一段关键帧之间 */
private fun frameAt(t: Float): Int {
    var i = 0
    while (i < WHALE_TIMES.size - 2 && t >= WHALE_TIMES[i + 1]) i++
    return i
}

/**
 * 当前时刻的形态坐标：相邻关键帧按 `WHALE_TIMES` 逐坐标线性插值，写进 [out] 并返回它。
 * 抽出来是为了能单测（绘制那条路只能真机看），见 `WhaleTailTest`。
 */
internal fun whalePoseAt(t: Float, out: FloatArray): FloatArray {
    val clamped = t.coerceIn(0f, 1f)
    val i = frameAt(clamped)
    val a = WHALE_FRAMES[i]
    val b = WHALE_FRAMES[i + 1]
    val span = WHALE_TIMES[i + 1] - WHALE_TIMES[i]
    val f = if (span <= 0f) 0f else ((clamped - WHALE_TIMES[i]) / span).coerceIn(0f, 1f)
    for (k in a.indices) out[k] = lerp(a[k], if (k < b.size) b[k] else a[k], f)
    return out
}

/** 把一帧的坐标写进这个 Path：`M x y` + 15 段 `C`（与 dsh 的命令结构一致） */
private fun Path.appendPose(pose: FloatArray) {
    reset()
    moveTo(pose[0], pose[1])
    var k = 2
    while (k + 5 < pose.size) {
        cubicTo(
            pose[k], pose[k + 1],
            pose[k + 2], pose[k + 3],
            pose[k + 4], pose[k + 5],
        )
        k += 6
    }
}
